import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LinkButton from 'flarum/common/components/LinkButton';
import CommentPost from 'flarum/forum/components/CommentPost';
import Switch from 'flarum/common/components/Switch';
import Button from 'flarum/common/components/Button';
import scan from './embed/scan';
import registerWidgets from './widgets';

/*
 * Everything here runs on every page for every visitor, so it is only the
 * wiring. The pages, the player, the editor and the in-post card are their
 * own chunks, fetched the first time something needs them.
 */
app.initializers.add('ernestdefoe-gauntlet', () => {
  app.routes['gauntlet.index'] = {
    path: '/quizzes',
    component: () => import(/* webpackChunkName: 'forum/pages/QuizzesPage', webpackMode: 'lazy-once' */ './pages/QuizzesPage')
  };
  app.routes['gauntlet.new'] = {
    path: '/quizzes/new',
    component: () => import(/* webpackChunkName: 'forum/pages/EditorPage', webpackMode: 'lazy-once' */ './pages/EditorPage')
  };
  app.routes['gauntlet.leaderboard'] = {
    path: '/quizzes/leaderboard',
    component: () => import(/* webpackChunkName: 'forum/pages/LeaderboardPage', webpackMode: 'lazy-once' */ './pages/LeaderboardPage')
  };
  app.routes['gauntlet.quiz'] = {
    path: '/quizzes/:id',
    component: () => import(/* webpackChunkName: 'forum/pages/QuizPage', webpackMode: 'lazy-once' */ './pages/QuizPage')
  };
  app.routes['gauntlet.edit'] = {
    path: '/quizzes/:id/edit',
    component: () => import(/* webpackChunkName: 'forum/pages/EditorPage', webpackMode: 'lazy-once' */ './pages/EditorPage')
  };
  extend(IndexSidebar.prototype, 'navItems', function (items) {
    if (!app.forum.attribute('canViewQuizzes') || app.forum.attribute('gauntletShowNav') === false) return;
    items.add('quizzes', m(LinkButton, {
      href: app.route('gauntlet.index'),
      icon: "fas fa-graduation-cap"
    }, app.translator.trans('ernestdefoe-gauntlet.forum.nav')), 4);
  });

  // A quiz link on a line of its own in a post becomes the playable quiz.
  // onupdate too: an edited post replaces its content, links and all.
  extend(CommentPost.prototype, ['oncreate', 'onupdate'], function () {
    if (app.forum.attribute('canViewQuizzes')) scan(this.element);
  });

  // "Add quiz" in the discussion and reply composers. Composers are lazy in
  // Flarum 2, so they are extended by module name.
  ['flarum/forum/components/DiscussionComposer', 'flarum/forum/components/ReplyComposer'].forEach(path => extend(path, 'headerItems', function (items) {
    if (!app.forum.attribute('canViewQuizzes') || !app.session.user) return;
    items.add('quiz', m(Button, {
      className: "Button Button--ua-reset ComposerBody-quiz",
      icon: "fas fa-graduation-cap",
      onclick: () => app.modal.show(() => import(/* webpackChunkName: 'forum/components/QuizPickerModal', webpackMode: 'lazy-once' */ './components/QuizPickerModal'), {
        composer: this.composer
      })
    }, app.translator.trans('ernestdefoe-gauntlet.forum.composer.add')), 1);
  }));
  extend('flarum/forum/components/SettingsPage', 'privacyItems', function (items) {
    if (!app.forum.attribute('canViewQuizzes')) return;
    const user = this.user;
    items.add('quizPrivate', m(Switch, {
      state: !!user.attribute('quizPrivate'),
      loading: this.quizPrivateLoading,
      onchange: value => {
        this.quizPrivateLoading = true;
        user.save({
          quizPrivate: value
        }).finally(() => {
          this.quizPrivateLoading = false;
          m.redraw();
        });
      }
    }, app.translator.trans('ernestdefoe-gauntlet.forum.settings.private')));
  });
  registerWidgets();
});flarum.reg.addChunkModule('ernestdefoe-gauntlet:forum/pages/QuizzesPage', '266', 'ernestdefoe-gauntlet', 'forum/pages/QuizzesPage');
flarum.reg.addChunkModule('ernestdefoe-gauntlet:forum/pages/QuizzesPage', '266', 'ernestdefoe-gauntlet', 'common/api');
